"""Transactional policy gate for proposals generated by the SOC workflow."""

import hashlib
import hmac
import json
import os
import time

from fastapi import HTTPException


SCHEMA = """
CREATE TABLE IF NOT EXISTS soc_proposals (
    id TEXT PRIMARY KEY, case_id TEXT NOT NULL REFERENCES cases(payment_id),
    case_version INTEGER NOT NULL, action TEXT NOT NULL, verdict TEXT NOT NULL,
    status TEXT NOT NULL, created_at DOUBLE PRECISION NOT NULL, resolved_at DOUBLE PRECISION,
    actor TEXT, note TEXT
);
CREATE INDEX IF NOT EXISTS soc_proposal_case ON soc_proposals(case_id, created_at);
CREATE TABLE IF NOT EXISTS soc_holds (
    case_id TEXT PRIMARY KEY REFERENCES cases(payment_id),
    expires_at DOUBLE PRECISION NOT NULL
);
CREATE TABLE IF NOT EXISTS soc_controls (
    key TEXT PRIMARY KEY, value INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS soc_feedback (
    seq INTEGER PRIMARY KEY AUTOINCREMENT, case_id TEXT NOT NULL REFERENCES cases(payment_id),
    verdict TEXT NOT NULL, rationale TEXT NOT NULL, created_at DOUBLE PRECISION NOT NULL
);
"""
TIERS = {"step_up": 1, "hold": 1, "watchlist": 1, "close_case": 1,
         "freeze": 2, "block_beneficiary": 2, "report": 2}
AUTO_CONFIDENCE = 0.95
AUTO_RISK_SCORE = 45
AUTO_HOLD_SCORE = 60
AUTO_ACTION_CAP = 10
HOLD_SECONDS = 900


def execution_mode(action, confidence, risk, max_tier, *, enabled):
    tier = TIERS.get(action, 0)
    if not tier:
        return None
    minimum_risk = AUTO_HOLD_SCORE if action == "hold" else AUTO_RISK_SCORE
    qualifies = confidence >= 0.98 and risk < 50 if action == "close_case" else (
        confidence >= AUTO_CONFIDENCE and risk >= minimum_risk)
    if enabled and tier == 1 and max_tier >= 1 and qualifies:
        return "queued"
    return "pending"


def eligible_action(action, payment_state, case_status):
    if action == "close_case":
        return payment_state == "SETTLED" and case_status == "VERIFIED"
    if case_status != "OPEN":
        return False
    if action in {"hold", "step_up"}:
        return payment_state == "STEP_UP_REQUIRED"
    if action in {"freeze", "block_beneficiary"}:
        return payment_state == "HELD"
    return action in {"watchlist", "report"}


def configured_tier():
    value = os.getenv("TRINETRA_AGENT_MAX_TIER", "0")
    return int(value) if value in {"0", "1", "2"} else 0


def sample_closure(case_id):
    digest = hashlib.sha256(case_id.encode()).digest()
    return int.from_bytes(digest[:4], "big") % 10 == 0


def challenge_code(proposal_id, case_id):
    secret = os.getenv("TRINETRA_ANALYST_KEY")
    if not secret:
        raise HTTPException(409, "Set a sandbox analyst key before issuing a challenge")
    return hmac.new(secret.encode(), f"trinetra-challenge:{proposal_id}:{case_id}".encode(), "sha256").hexdigest()[:48]


class Actions:
    def __init__(self, ledger):
        self.ledger = ledger

    @staticmethod
    def killed(db):
        row = db.execute("SELECT value FROM soc_controls WHERE key='kill_switch'").fetchone()
        return bool(row and row["value"])

    def register(self, db, job, verdict):
        trigger = job["trigger_kind"]
        if trigger not in {"PAYMENT_EVALUATED", "SOC_WATCH_SIGNAL", "BACKFILL", "CHALLENGE_VERIFIED"}:
            return
        case_id = job["case_id"]
        payment = self.ledger.result(self.ledger.payment(db, case_id))
        action = verdict["recommended_action"]
        case = db.execute("SELECT status FROM cases WHERE payment_id=?", (case_id,)).fetchone()
        if trigger == "CHALLENGE_VERIFIED":
            if (os.getenv("TRINETRA_AGENT_AUTO_CLOSE") != "1" or verdict["verdict"] != "benign"
                    or verdict["confidence"] < 0.98 or payment["risk_score"] >= 50
                    or self.ledger.blocked(db, payment["recipient"])):
                return
            action = "close_case"
        auto = trigger == "PAYMENT_EVALUATED" or (action == "close_case" and not sample_closure(case_id))
        mode = execution_mode(action, verdict["confidence"], payment["risk_score"], configured_tier(),
                              enabled=auto and not self.killed(db))
        if mode and eligible_action(action, payment["state"], case["status"]):
            db.execute("INSERT INTO soc_proposals(id,case_id,case_version,action,verdict,status,created_at) "
                       "VALUES (?,?,?,?,?,?,?) ON CONFLICT(id) DO NOTHING",
                       (job["id"], case_id, job["case_version"], action, json.dumps(verdict), mode, time.time()))
            self.ledger.event(db, case_id, "SOC_PROPOSAL", "soc-decision",
                              {"proposal_id": job["id"], "action": action, "status": mode})

    def queued(self):
        with self.ledger.tx() as db:
            row = db.execute("SELECT id,case_id FROM soc_proposals WHERE status='queued' "
                             "ORDER BY created_at,id LIMIT 1").fetchone()
            return dict(row) if row else None

    def apply(self, case_id, proposal_id, *, review=None):
        with self.ledger.tx(write=True) as db:
            proposal = db.execute("SELECT * FROM soc_proposals WHERE case_id=? AND id=?",
                                  (case_id, proposal_id)).fetchone()
            if proposal is None:
                raise HTTPException(404, "Proposal unavailable")
            if proposal["status"] not in {"pending", "queued"}:
                return {"status": proposal["status"]}
            if not review and proposal["status"] != "queued":
                raise HTTPException(409, "Proposal requires analyst approval")
            case = db.execute("SELECT * FROM cases WHERE payment_id=?", (case_id,)).fetchone()
            payment = self.ledger.result(self.ledger.payment(db, case_id))
            action = proposal["action"]
            now = time.time()
            actor = "sandbox-analyst" if review else "soc-agent"
            note = review["note"] if review else "Automatic Tier 1 review"
            blocked = self.killed(db) or TIERS[action] > configured_tier()
            if action == "close_case":
                blocked |= (os.getenv("TRINETRA_AGENT_AUTO_CLOSE") != "1"
                            or self.ledger.blocked(db, payment["recipient"]))
            if not review:
                recent = db.execute("SELECT count(*) AS total FROM soc_proposals "
                                    "WHERE actor='soc-agent' AND status='applied' AND resolved_at>?",
                                    (now - 3600,)).fetchone()["total"]
                verdict = json.loads(proposal["verdict"])
                blocked = (blocked or recent >= AUTO_ACTION_CAP or
                           execution_mode(action, verdict["confidence"], payment["risk_score"],
                                          configured_tier(), enabled=True) != "queued")
            if review and review["decision"] == "reject":
                status = "rejected"
            elif case["version"] != proposal["case_version"] or not eligible_action(action, payment["state"], case["status"]):
                status = "stale"
            elif blocked:
                if review:
                    raise HTTPException(409, "Action is disabled by the SOC controls")
                status = "pending"
                note = "Automatic execution is disabled or rate limited"
            else:
                self.effect(db, payment, proposal_id, action, now, actor, note)
                status = "applied"
            db.execute("UPDATE soc_proposals SET status=?,resolved_at=?,actor=?,note=? WHERE id=?",
                       (status, now, actor, note, proposal_id))
            self.ledger.event(db, case_id, "SOC_ACTION", actor,
                              {"proposal_id": proposal_id, "action": action, "outcome": status, "note": note})
            return {"status": status}

    def effect(self, db, payment, proposal_id, action, now, actor, note):
        case_id = payment["payment_id"]
        status = "OPEN"
        if action == "step_up":
            active = db.execute("SELECT 1 FROM challenges WHERE payment_id=? AND expires>?", (case_id, now)).fetchone()
            if not active:
                self.ledger.put_challenge(db, case_id, challenge_code(proposal_id, case_id), now)
        elif action == "hold":
            db.execute("INSERT INTO soc_holds VALUES (?,?) ON CONFLICT(case_id) "
                       "DO UPDATE SET expires_at=excluded.expires_at", (case_id, now + HOLD_SECONDS))
        elif action in {"freeze", "block_beneficiary"}:
            db.execute("INSERT INTO restrictions VALUES (?) ON CONFLICT(account) DO NOTHING", (payment["recipient"],))
            status = "CONFIRM_FREEZE" if action == "freeze" else "BLOCK_BENEFICIARY"
        elif action == "report":
            self.ledger.event(db, case_id, "SOC_REPORT_APPROVED", actor, {"note": note, "run_id": proposal_id})
        elif action == "watchlist":
            self.ledger.monitor.schedule(db, case_id, now, expedited=True)
        elif action == "close_case":
            status = "CLOSED_BENIGN"
        db.execute("UPDATE cases SET status=?,version=version+1 WHERE payment_id=?", (status, case_id))

    def active_code(self, case_id):
        with self.ledger.tx() as db:
            challenge = db.execute("SELECT proof_hash FROM challenges WHERE payment_id=? AND expires>? AND attempts<5",
                                   (case_id, time.time())).fetchone()
            proposals = db.execute("SELECT id FROM soc_proposals WHERE case_id=? AND action='step_up' "
                                   "AND status='applied' ORDER BY resolved_at DESC LIMIT 5", (case_id,)).fetchall()
        if challenge:
            for proposal in proposals:
                code = challenge_code(proposal["id"], case_id)
                if hmac.compare_digest(challenge["proof_hash"], hashlib.sha256(code.encode()).hexdigest()):
                    return code
        raise HTTPException(404, "No active SOC challenge")

    def set_kill_switch(self, enabled):
        with self.ledger.tx(write=True) as db:
            db.execute("INSERT INTO soc_controls VALUES ('kill_switch',?) ON CONFLICT(key) "
                       "DO UPDATE SET value=excluded.value", (int(enabled),))
            return {"kill_switch": enabled, "max_tier": configured_tier()}

    def override(self, case_id, version, verdict, note):
        with self.ledger.tx(write=True) as db:
            row = db.execute("SELECT version FROM cases WHERE payment_id=?", (case_id,)).fetchone()
            if not row or row["version"] != version:
                raise HTTPException(409, "Refresh the case before overriding the verdict")
            db.execute("INSERT INTO soc_feedback(case_id,verdict,rationale,created_at) VALUES (?,?,?,?)",
                       (case_id, verdict, note, time.time()))
            db.execute("UPDATE cases SET version=version+1 WHERE payment_id=?", (case_id,))
            self.ledger.event(db, case_id, "SOC_VERDICT_OVERRIDE", "sandbox-analyst", {"verdict": verdict, "note": note})
            return {"version": version + 1, "verdict": verdict}

    def details(self, db, case_id):
        audit = db.execute("SELECT seq,run_id,role,tool,outcome,created_at FROM soc_tool_audit "
                           "WHERE case_id=? ORDER BY seq DESC LIMIT 80", (case_id,)).fetchall()
        proposals = db.execute("SELECT id,case_version,action,verdict,status,actor,note FROM soc_proposals "
                               "WHERE case_id=? ORDER BY created_at DESC,id DESC LIMIT 20", (case_id,)).fetchall()
        feedback = db.execute("SELECT verdict,rationale,created_at FROM soc_feedback WHERE case_id=? "
                              "ORDER BY seq DESC LIMIT 1", (case_id,)).fetchone()
        hold = db.execute("SELECT expires_at FROM soc_holds WHERE case_id=? AND expires_at>?",
                          (case_id, time.time())).fetchone()
        return {
            "timeline": [dict(row) for row in reversed(audit)],
            "watch": self.ledger.monitor.details(db, case_id),
            "proposals": [dict(row) | {"verdict": json.loads(row["verdict"])} for row in proposals],
            "feedback": dict(feedback) if feedback else None,
            "hold_until": hold["expires_at"] if hold else None,
            "kill_switch": self.killed(db), "max_tier": configured_tier(),
        }
